import{_ as t,o as r,c as a,a0 as n}from"./chunks/framework.BxrwG5q5.js";const f=JSON.parse('{"title":"Concepts & Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"guide/concepts.md","filePath":"guide/concepts.md"}'),o={name:"guide/concepts.md"};function s(i,e,c,g,l,d){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="concepts-glossary" tabindex="-1">Concepts &amp; Glossary <a class="header-anchor" href="#concepts-glossary" aria-label="Permalink to &quot;Concepts &amp; Glossary&quot;">​</a></h1><blockquote><p>See also: <a href="/config/guide/getting-started.html">Quick Start</a> · <a href="/config/contributing/architecture.html">Architecture</a> · <a href="/config/api/">SDK Reference</a></p></blockquote><p>A quick reference of key terminology used throughout the documentation.</p><hr><p><strong>Config / Feature Flag</strong> — A key-value pair that controls application behavior at runtime. Configs can be boolean flags, numbers, strings, JSON, or arrays. <a href="/config/guide/getting-started.html">Learn more →</a></p><p><strong>Context</strong> — The set of user attributes sent to the API for evaluation (e.g., <code>userId</code>, <code>plan</code>, <code>country</code>). Context drives targeting rules and segment membership. <a href="/config/guide/scopes.html">Learn more →</a></p><p><strong>Segments</strong> — Reusable audience groups defined by conditions on context attributes. Define once, reference across many flags. <a href="/config/features/segments.html">Learn more →</a></p><p><strong>Targeting Rules</strong> — Rules that match context attributes or segment membership to return specific config values. Evaluated in priority order. <a href="/config/features/targeting.html">Learn more →</a></p><p><strong>Rollouts</strong> — Percentage-based gradual feature release using deterministic hashing (<code>MurmurHash3(flagKey:userId) % 100</code>). Same user always gets the same bucket. <a href="/config/features/rollouts.html">Learn more →</a></p><p><strong>Prerequisites</strong> — Flag dependencies where Flag B is only active if Flag A meets a condition. Prevents inconsistent feature states. <a href="/config/features/prerequisites.html">Learn more →</a></p><p><strong>Scheduling</strong> — Time-based one-shot flag activation. Set a date/time and target value; the flag switches permanently at that moment. <a href="/config/features/scheduling.html">Learn more →</a></p><p><strong>Environments</strong> — Isolated deployment stages (development, staging, production) with independent configs, API keys, and targeting rules. <a href="/config/features/environments.html">Learn more →</a></p><p><strong>API Keys</strong> — Client keys (<code>cid_</code>) trigger server-side evaluation (rules never exposed to browser). Server keys (<code>svr_</code>) return full flag data for client-side evaluation. <a href="/config/api/">Learn more →</a></p><p><strong>Evaluation Pipeline</strong> — The order in which flags are resolved: archived → prerequisites → overrides → schedule → targeting → rollout → default. <a href="/config/contributing/architecture.html">Learn more →</a></p><p><strong>Loading Strategies</strong> — How the SDK fetches data on init: <strong>optimistic</strong> (instant defaults, background fetch), <strong>pessimistic</strong> (blocks until data arrives), <strong>deferred</strong> (no fetch until you trigger it). <a href="/config/guide/loading-strategies.html">Learn more →</a></p><p><strong>Circuit Breaker</strong> — The SDK stops making requests for 5 minutes after receiving fatal errors (401/403), preventing wasted bandwidth on misconfigured clients. <a href="/config/api/">Learn more →</a></p><p><strong>RBAC</strong> — Role-based access control with three levels: Viewer (read-only), Editor (read/write configs), Admin (full access including team and API keys). <a href="/config/features/team.html">Learn more →</a></p>',17)])])}const p=t(o,[["render",s]]);export{f as __pageData,p as default};
